effect.shader:
float hashV(vec2 p) {
return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}
float noiseV(vec2 p) {
vec2 i = floor(p);
vec2 f = fract(p);
f = f*f*(3.0-2.0*f);
return mix(
mix(hashV(i),           hashV(i+vec2(1,0)), f.x),
mix(hashV(i+vec2(0,1)), hashV(i+vec2(1,1)), f.x),
f.y
);
}
void main() {
vec2 uv  = acScreenNorm;
float t  = acTime;
float sc = effectScale;
vec4 src = texture2DCv(inputImg.texture, clamp(uv, 0.0, 1.0));
vec2 sampleUV = uv;
if (lowResOn) {
float res = max(lowResPct, 0.05);
vec2 blockSize = vec2(1.0) / (acPreviewSize * res);
sampleUV = floor(uv / blockSize) * blockSize + blockSize * 0.5;
sampleUV = clamp(sampleUV, 0.0, 1.0);
}
if (tvDistOn) {
float tvWave = noiseV(vec2(uv.y * 5.0, t * 2.0)) * 2.0 - 1.0;
sampleUV.x += tvWave * tvDistAmt * moreDamage;
sampleUV = clamp(sampleUV, 0.0, 1.0);
}
vec3 col = texture2DCv(inputImg.texture, sampleUV).rgb;
if (glitchOn) {
float gTime  = floor(t * glitchSpeed);
float bSize  = glitchSize * sc;
vec2  block  = floor(uv / max(bSize, 0.01));
float gRnd   = hashV(block + vec2(gTime, randomSeed * 100.0));
float thresh = 1.0 - glitchAmt * moreOften;
float fired  = step(thresh, gRnd);
float cRnd   = hashV(vec2(gTime + 5.0, randomSeed));
fired *= step(1.0 - glitchChance * 2.0, cRnd);
float dispX  = (hashV(block + vec2(gTime + 1.0, 0.5)) * 2.0 - 1.0) * bSize * 3.0;
vec3  gCol   = texture2DCv(inputImg.texture,
clamp(sampleUV + vec2(dispX * fired, 0.0), 0.0, 1.0)).rgb;
col = mix(col, gCol, fired);
}
if (colorSepOn) {
float cRnd  = hashV(vec2(floor(t * 4.0), randomSeed + 7.0));
float fired = step(1.0 - colorSepChance * 2.0, cRnd);
float ca    = colorSepAmt * moreDamage * fired;
col.r = mix(col.r,
texture2DCv(inputImg.texture, clamp(sampleUV + vec2( ca, 0), 0.0, 1.0)).r,
fired);
col.b = mix(col.b,
texture2DCv(inputImg.texture, clamp(sampleUV - vec2( ca, 0), 0.0, 1.0)).b,
fired);
}
float luma = dot(col, vec3(0.2126, 0.7152, 0.0722));
luma = clamp(luma + srcBrightness, 0.0, 1.0);
luma = clamp((luma - 0.5) * (1.0 + srcContrast) + 0.5, 0.0, 1.0);
if (colorizeOn) {
vec3 shadow    = vec3(shadowR,    shadowG,    shadowB);
vec3 midtone   = vec3(midtoneR,   midtoneG,   midtoneB);
vec3 highlight = vec3(highlightR, highlightG, highlightB);
vec3 colorized = mix(shadow, midtone,   smoothstep(0.0, 0.5, luma));
colorized      = mix(colorized, highlight, smoothstep(0.5, 1.0, luma));
col = mix(col, colorized, colorizeAmt);
}
if (glowOn) {
float gr    = glowRadius * 15.0 * sc;
vec2  px    = vec2(gr / acPreviewSize.x, gr / acPreviewSize.y);
float lumaC = dot(col, vec3(0.2126, 0.7152, 0.0722));
float gmask = smoothstep(glowThresh - 0.1, glowThresh + 0.1, lumaC);
vec3 g0 = texture2DCv(inputImg.texture, clamp(sampleUV+vec2( px.x, 0.0), 0.0, 1.0)).rgb;
vec3 g1 = texture2DCv(inputImg.texture, clamp(sampleUV-vec2( px.x, 0.0), 0.0, 1.0)).rgb;
vec3 g2 = texture2DCv(inputImg.texture, clamp(sampleUV+vec2(0.0,  px.y), 0.0, 1.0)).rgb;
vec3 g3 = texture2DCv(inputImg.texture, clamp(sampleUV-vec2(0.0,  px.y), 0.0, 1.0)).rgb;
vec3 gBlur = (g0 + g1 + g2 + g3) * 0.25 * gmask;
vec3 glow  = gBlur * glowIntensity * moreDamage;
col = 1.0 - (1.0 - col) * (1.0 - glow * 0.7);
}
if (scanLinesOn) {
float sd  = float(scanDir);
float sDist = max(scanDistance * sc, 1.0);
float sThk  = scanThickness / sDist * 0.5;
sThk = clamp(sThk, 0.01, 0.49);
float hMask = 1.0;
float vMask = 1.0;
if (sd < 0.5 || sd > 1.5) {
float hp = fract(uv.y * acPreviewSize.y / sDist);
hMask = mix(0.25, 1.0,
1.0 - smoothstep(sThk*0.5, sThk, hp) * (1.0 - smoothstep(1.0-sThk, 1.0-sThk*0.5, hp)));
}
if (sd > 0.5) {
float vp = fract(uv.x * acPreviewSize.x / sDist);
vMask = mix(0.25, 1.0,
1.0 - smoothstep(sThk*0.5, sThk, vp) * (1.0 - smoothstep(1.0-sThk, 1.0-sThk*0.5, vp)));
}
col *= hMask * vMask;
}
if (linesOn) {
float luPos  = fract(uv.y + t * lineSpeed);
float luMask = smoothstep(0.0, lineHeight, luPos) *
(1.0 - smoothstep(lineHeight, lineHeight*1.1, luPos));
float ldPos  = fract(uv.y - t * lineSpeed * 0.7);
float ldMask = smoothstep(0.0, lineHeight, ldPos) *
(1.0 - smoothstep(lineHeight, lineHeight*1.1, ldPos));
float lineMask = max(luMask, ldMask);
col = mix(col, col * 1.5, lineMask * 0.6);
}
if (staticOn) {
float sNoise = hashV(vec2(
floor(uv.x * acPreviewSize.x) + floor(t * 30.0) * 1000.0,
floor(uv.y * acPreviewSize.y) + randomSeed * 500.0
));
col += (sNoise - 0.5) * staticOpacity * moreDamage;
}
if (flickerOn) {
float fRnd  = hashV(vec2(floor(t * 15.0), randomSeed * 30.0));
float fired = step(1.0 - flickerChance * 2.0, fRnd);
float flOp  = mix(1.0, flickerMin, fired);
col *= flOp;
}
col = clamp(col, 0.0, 1.0);
gl_FragColor = vec4(mix(src.rgb, col, blend), src.a);
}
